import { Document, Page, Text, StyleSheet, View } from '@react-pdf/renderer';

const Invoice = ({ order }) => {
  return (
    <Document>
      <Page style={styles.body}>
        <Text style={styles.header}>~ {new Date().toLocaleString()} ~</Text>

        <Text style={styles.title}>Order Invoice</Text>

        <Text style={styles.author}>MERN Ecommerce</Text>

        <Text style={styles.subtitle}>Order Summary</Text>

        {/* Table */}
        <View style={styles.table}>
          {/* Header */}
          <View style={styles.tableRow}>
            <Text style={[styles.tableHeader, styles.titleColumn]}>Title</Text>

            <Text style={[styles.tableHeader, styles.priceColumn]}>Price</Text>

            <Text style={[styles.tableHeader, styles.brandColumn]}>Brand</Text>

            <Text style={[styles.tableHeader, styles.colorColumn]}>Color</Text>

            <Text style={[styles.tableHeader, styles.quantityColumn]}>
              Quantity
            </Text>
          </View>

          {/* Products */}
          {order.products.map((item, index) => (
            <View style={styles.tableRow} key={index}>
              <Text style={[styles.tableCell, styles.titleColumn]}>
                {item.product.title}
              </Text>

              <Text style={[styles.tableCell, styles.priceColumn]}>
                ${item.product.price}
              </Text>

              <Text style={[styles.tableCell, styles.brandColumn]}>
                {item.product.brand}
              </Text>

              <Text style={[styles.tableCell, styles.colorColumn]}>
                {item.product.color}
              </Text>

              <Text style={[styles.tableCell, styles.quantityColumn]}>
                {item.quantity}
              </Text>
            </View>
          ))}
        </View>

        <Text style={styles.text}>
          Order Date:{' '}
          {new Date(order.paymentIntent.created * 1000).toLocaleString()}
        </Text>

        <Text style={styles.text}>Order ID: {order.paymentIntent.id}</Text>

        <Text style={styles.text}>Order Status: {order.orderStatus}</Text>

        <Text style={styles.text}>
          Total Paid: ${order.paymentIntent.amount / 100}
        </Text>

        <Text style={styles.footer}>~ Thank you for shopping with us ~</Text>
      </Page>
    </Document>
  );
};

const styles = StyleSheet.create({
  body: {
    paddingTop: 35,
    paddingBottom: 65,
    paddingHorizontal: 35,
  },

  title: {
    fontSize: 24,
    textAlign: 'center',
  },

  author: {
    fontSize: 12,
    textAlign: 'center',
    marginBottom: 40,
  },

  subtitle: {
    fontSize: 18,
    margin: 12,
  },

  text: {
    margin: 12,
    fontSize: 14,
    textAlign: 'justify',
  },

  header: {
    fontSize: 12,
    marginBottom: 20,
    textAlign: 'center',
    color: 'grey',
  },

  footer: {
    fontSize: 12,
    marginTop: 30,
    textAlign: 'center',
    color: 'grey',
  },

  // Table
  table: {
    width: '100%',
    marginTop: 10,
    marginBottom: 20,
  },

  tableRow: {
    flexDirection: 'row',
    borderBottomWidth: 1,
    borderBottomColor: '#cccccc',
    borderBottomStyle: 'solid',
    alignItems: 'center',
    minHeight: 30,
  },

  tableHeader: {
    fontSize: 10,
    fontWeight: 'bold',
    textAlign: 'center',
    padding: 5,
  },

  tableCell: {
    fontSize: 9,
    textAlign: 'center',
    padding: 5,
  },

  titleColumn: {
    width: '30%',
  },

  priceColumn: {
    width: '15%',
  },

  brandColumn: {
    width: '15%',
  },

  colorColumn: {
    width: '15%',
  },

  quantityColumn: {
    width: '25%',
  },
});

export default Invoice;
